public class ImportingUtilities {

    // other methods

    /**
     * Allocates a new {@link File} inside {@code dir} with a unique name derived from {@code name}.
     * The method protects against directory‑traversal attacks by normalizing the resolved path
     * and ensuring it remains within {@code dir}. It also strips query parameters from the
     * supplied name and guarantees that the resulting file does not overwrite existing files.
     *
     * @param dir  the target directory where the file should be created; must not be {@code null}
     * @param name the desired file name; may contain relative path components or query strings
     * @return a {@link File} instance pointing to a non‑existing file inside {@code dir}
     * @throws NullPointerException     if {@code dir} or {@code name} is {@code null}
     * @throws IllegalArgumentException if the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new NullPointerException("Directory cannot be null");
        }
        if (name == null) {
            throw new NullPointerException("File name cannot be null");
        }

        // Remove any query component (e.g., "?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the target path against the base directory and normalize it
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still under the intended directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                    "Attempt to create a file outside the target directory: " + name);
        }

        File file = targetPath.toFile();

        // Determine prefix and suffix for generating unique filenames
        int dot = name.indexOf('.');
