    @Override
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        // No path info – nothing to forward to
        if (pathInfo == null || pathInfo.isEmpty()) {
            return null;
        }

        // Strip the leading slash that Servlet containers prepend to pathInfo
        String trimmed = pathInfo.startsWith("/") ? pathInfo.substring(1) : pathInfo;

        // Normalize the path to collapse any "." or ".." segments
        Path normalizedPath = Paths.get(trimmed).normalize();

        // Reject absolute paths or any attempt to navigate above the root
        if (normalizedPath.isAbsolute()
                || normalizedPath.startsWith("..")
                || normalizedPath.toString().contains("..")) {
            return null;
        }

        // Whitelist allowed characters: letters, digits, underscore, hyphen, dot, and slash
        if (!normalizedPath.toString().matches("[a-zA-Z0-9_\\-./]*")) {
            return null;
        }

        // Return the original pathInfo (with leading slash) so that JSPWiki can resolve it correctly
        return pathInfo;
