private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory, Object principalObj, Object credentialsObj) throws NamingException {
    if (!(principalObj instanceof String)) {
        throw new IllegalArgumentException("Principal must be a String");
    }
    if (!(credentialsObj instanceof String || credentialsObj instanceof char[])) {
        throw new IllegalArgumentException("Credentials must be a String or char[]");
    }
    String principal = (String) principalObj;
    String credentials;
    if (credentialsObj instanceof String) {
        credentials = (String) credentialsObj;
    } else {
        credentials = new String((char[]) credentialsObj);
    }
    if (principal.isEmpty() || credentials.isEmpty()) {
        throw new IllegalArgumentException("Principal and credentials must not be empty");
    }

    JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());
    env.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());

    LdapContext ctx = null;
    try {
        ctx = new InitialLdapContext(env, null);

        StartTlsRequest startTlsRequest = new StartTlsRequest();
        StartTlsResponse tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate();

        // After TLS negotiation, set credentials and reconnect
        ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
        ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);
        ctx.reconnect(); // rebind with credentials over TLS

        return ctx;
    } catch (IOException e) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': ", server(jndiLdapContextFactory), e));
        throw new CommunicationException(e.getMessage(), e);
    } catch (NamingException ne) {
        LdapUtils.closeContext(ctx);
        securityLog.warn(withRealm("Authentication failed for user '%s' against '%s': %s", principal, server(jndiLdapContextFactory), ne.getMessage()));
        throw ne;
    } catch (Throwable t) {
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Unexpected failure to negotiate TLS connection with '%s': ", server(jndiLdapContextFactory), t));
        throw t;
    }
}

